// Data types formerly generated by prost-build from pathinfo.proto.
// Now plain Rust structs with serde derives, serialized with postcard.
// NOTE: `Bytes` and `serde` are imported by the parent module (proto/mod.rs).
use serde::{Deserialize, Serialize};

/// PathInfo shows information about a Nix Store Path.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct PathInfo {
    pub entry: Option<snix_castore::proto::Entry>,
    pub references: Vec<Bytes>,
    pub narinfo: Option<NarInfo>,
}

/// Represents a path in the Nix store.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct StorePath {
    pub name: String,
    
    pub digest: Bytes,
}

/// NAR metadata and signatures.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct NarInfo {
    pub nar_size: u64,
    
    pub nar_sha256: Bytes,
    pub signatures: Vec<nar_info::Signature>,
    pub reference_names: Vec<String>,
    pub deriver: Option<StorePath>,
    pub ca: Option<nar_info::Ca>,
}

pub mod nar_info {
    use super::*;

    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Signature {
        pub name: String,
        
        pub data: Bytes,
    }

    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub struct Ca {
        pub r#type: i32,
        
        pub digest: Bytes,
    }

    pub mod ca {
        use serde::{Deserialize, Serialize};

        #[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, Serialize, Deserialize)]
        #[repr(i32)]
        pub enum Hash {
            NarSha256 = 0,
            NarSha1 = 1,
            NarSha512 = 2,
            NarMd5 = 3,
            TextSha256 = 4,
            FlatSha1 = 5,
            FlatMd5 = 6,
            FlatSha256 = 7,
            FlatSha512 = 8,
            NarBlake3 = 9,
            FlatBlake3 = 10,
        }

        impl From<Hash> for i32 {
            fn from(h: Hash) -> i32 {
                h as i32
            }
        }

        impl Hash {
            pub fn as_str_name(&self) -> &'static str {
                match self {
                    Self::NarSha256 => "NAR_SHA256",
                    Self::NarSha1 => "NAR_SHA1",
                    Self::NarSha512 => "NAR_SHA512",
                    Self::NarMd5 => "NAR_MD5",
                    Self::TextSha256 => "TEXT_SHA256",
                    Self::FlatSha1 => "FLAT_SHA1",
                    Self::FlatMd5 => "FLAT_MD5",
                    Self::FlatSha256 => "FLAT_SHA256",
                    Self::FlatSha512 => "FLAT_SHA512",
                    Self::NarBlake3 => "NAR_BLAKE3",
                    Self::FlatBlake3 => "FLAT_BLAKE3",
                }
            }

            pub fn from_str_name(value: &str) -> Option<Self> {
                match value {
                    "NAR_SHA256" => Some(Self::NarSha256),
                    "NAR_SHA1" => Some(Self::NarSha1),
                    "NAR_SHA512" => Some(Self::NarSha512),
                    "NAR_MD5" => Some(Self::NarMd5),
                    "TEXT_SHA256" => Some(Self::TextSha256),
                    "FLAT_SHA1" => Some(Self::FlatSha1),
                    "FLAT_MD5" => Some(Self::FlatMd5),
                    "FLAT_SHA256" => Some(Self::FlatSha256),
                    "FLAT_SHA512" => Some(Self::FlatSha512),
                    "NAR_BLAKE3" => Some(Self::NarBlake3),
                    "FLAT_BLAKE3" => Some(Self::FlatBlake3),
                    _ => None,
                }
            }
        }
    }
}

/// Parameters to lookup a single PathInfo.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct GetPathInfoRequest {
    pub by_what: Option<get_path_info_request::ByWhat>,
}

pub mod get_path_info_request {
    use super::*;

    #[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
    pub enum ByWhat {
        ByOutputHash(Bytes),
    }
}

/// Parameters to list PathInfo objects (currently no filtering).
#[derive(Clone, Copy, Debug, Default, PartialEq, Serialize, Deserialize)]
pub struct ListPathInfoRequest {}

/// Response from CalculateNAR.
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
pub struct CalculateNarResponse {
    pub nar_size: u64,
    
    pub nar_sha256: Bytes,
}
